#!/usr/bin/env python3
"""Build the weather card's scene layers.

Run:  python3 art/build.py [out dir]      (default: www/weather in this repository)
Writes plain SVG files (CSS animations inside, no scripts), which the Bubble
weather card stacks as CSS backgrounds, chosen from sensor.overview_sky's
attributes (packages/overview.yaml):

  kl-skyline-{day,grey,snow,twilight,night}-{spring,summer,autumn,winter}.svg
                                                   city, coloured for the light and the season
  kl-windows.svg                                   lit windows (hand-drawn, copied from
                                                   art/kl-windows.svg)
  kl-snowcap-{day,twilight,night}.svg              snow on roofs, ledges, trees, hills
  kl-match-{day,night}.svg                         FCK home game: floodlights, flags, crest
  kl-xmas-{day,night}.svg                          Christmas tree and string lights
  kl-sunball.svg, kl-sunlow.svg                    sun (120 px tile, placed by the card)
  kl-moon-{1..7}.svg                               moon phase (90 px tile, placed by the card)
  kl-stars.svg                                     twinkling stars, a rare shooting star
  kl-clouds-{partly,overcast}-{pal}-{calm,windy}-{l,r}.svg  drifting clouds, two depths
  kl-lightning.svg                                 sky flashes and bolts
  kl-fog-{day,night}.svg                           mist drifting over the town
  kl-planes-{day,twilight,night}.svg               C-17 and C-5 from Ramstein
  kl-{rain,pour,hail,sleet,snow}-{m3..p3}.svg      precipitation tiles (repeat), slanted
                                                   by the wind (m = to the left, p = right)

The view looks south: east is on the left, so the sun rises on the left.

All of it honours prefers-reduced-motion. Bump the card's ?v= after a rebuild.
"""
import math
import random
import shutil
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
OUT = Path(sys.argv[1]) if len(sys.argv) > 1 else HERE.parent / "www" / "weather"
OUT.mkdir(parents=True, exist_ok=True)
shutil.copyfile(HERE / "kl-windows.svg", OUT / "kl-windows.svg")

RM = "@media (prefers-reduced-motion: reduce){*{animation:none!important}}"


def write(name, body):
    (OUT / name).write_text(body.strip() + "\n")


def hexmix(a, b, t):
    a = [int(a[i:i + 2], 16) for i in (1, 3, 5)]
    b = [int(b[i:i + 2], 16) for i in (1, 3, 5)]
    return "#" + "".join(f"{round(x + (y - x) * t):02x}" for x, y in zip(a, b))


