# --------------------------------------------------------------------------
# Windows of the town (2026-11-22). Coordinates inside the town group
# (translate(-40,0)); small windows match the lit ones in kl-windows.svg.
# --------------------------------------------------------------------------
def _rects(xs, ys, w, h):
    return " ".join(f"M{x} {y} h{w} v{h} h-{w}Z" for y in ys for x in xs)


def _arch(x, y, w, h):
    r = w / 2
    return f"M{x} {y + r} a{r} {r} 0 0 1 {w} 0 V{y + h} H{x}Z"


def _rose(cx, cy, r):
    return f"M{cx - r} {cy} a{r} {r} 0 1 0 {2 * r} 0 a{r} {r} 0 1 0 {-2 * r} 0Z"


