def overlay(main, town, humberg, style="", defs=""):
    return f"""
<svg xmlns="http://www.w3.org/2000/svg" viewBox="20 0 990 250" preserveAspectRatio="xMidYMax slice">
  <defs>{defs}</defs>
  <style>{style}
    {RM}</style>
  <g transform="scale(1,1.25)">
    {main}
    <g transform="translate(-40,0)">{town}</g>
    <g transform="translate(-100,0)">{humberg}</g>
  </g>
</svg>"""


def flat(x1, x2, y, t=1.8):
    return f"M{x1 - .6} {y - .9} h{x2 - x1 + 1.2} v{t} h{-(x2 - x1 + 1.2)}Z"


def gable(x1, y1, xa, ya, x2, y2, t=2.2):
    return (f"M{x1 - .7} {y1 + .3} L{xa} {ya - .9} L{x2 + .7} {y2 + .3} L{x2 - 1.8} {y2 + .3} "
            f"L{xa} {ya + t - .9} L{x1 + 1.8} {y1 + .3}Z")


