# Match day at the Betzenberg: floodlights (beams after dark), red-and-white
# flags on the roof and a simple club crest in red and white on the stand.
def match(pal):
    night = pal == "night"
    flags = "".join(f'<path d="M{x} 99 v-5.5" stroke="#d8dde3" stroke-width=".5"/>'
                    f'<path class="fl{i % 2}" d="M{x + .25} 93.5 l4.6 1.3 l-4.6 1.3Z" fill="{"#e2001a" if i % 2 == 0 else "#ffffff"}"/>'
                    for i, x in enumerate(range(68, 236, 12)))
    beams = ""
    if night:
        beams = ('<path d="M58 83 L84 103 L150 103Z" fill="url(#beam)"/>'
                 '<path d="M242 83 L216 103 L150 103Z" fill="url(#beam)"/>'
                 '<ellipse cx="150" cy="101" rx="104" ry="16" fill="#fff6dc" opacity=".22" filter="url(#soft)"/>'
                 '<rect x="66" y="105" width="168" height="2" fill="#fff4d6" opacity=".55"/>')
    heads = (f'<g fill="#fffbe8"><circle cx="58" cy="82" r="{9 if night else 5}" opacity="{.6 if night else .5}" filter="url(#soft)"/>'
             f'<circle cx="242" cy="82" r="{9 if night else 5}" opacity="{.6 if night else .5}" filter="url(#soft)"/>'
             '<rect x="52" y="80" width="12" height="3"/><rect x="236" y="80" width="12" height="3"/></g>'
             )
    crest = ('<g transform="translate(150 104.6) scale(1.6 1.28)">'
             '<path d="M-8.5 0 h17 v7.5 q0 7 -8.5 10 q-8.5 -3 -8.5 -10Z" fill="#e2001a" stroke="#ffffff" stroke-width=".9"/>'
             '<text x="0" y="9.6" font-size="6.2" font-family="Arial Black, Arial, Helvetica, sans-serif" '
             'font-weight="900" text-anchor="middle" fill="#ffffff">FCK</text></g>')
    defs = ('<linearGradient id="beam" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fffbe8" stop-opacity=".55"/>'
            '<stop offset="1" stop-color="#fffbe8" stop-opacity=".08"/></linearGradient>'
            '<filter id="soft" x="-100%" y="-100%" width="300%" height="300%"><feGaussianBlur stdDeviation="3"/></filter>')
    style = (".fl0{animation:wave 1.4s ease-in-out infinite alternate;transform-box:fill-box;transform-origin:left center}"
             ".fl1{animation:wave 1.4s ease-in-out infinite alternate-reverse;transform-box:fill-box;transform-origin:left center}"
             "@keyframes wave{from{transform:scaleY(.7) skewY(-6deg)}to{transform:scaleY(1) skewY(6deg)}}")
    return overlay(beams + heads + flags + crest, "", "", style, defs)


