write("kl-match-night.svg", match("night"))


# Christmas (Monday after Totensonntag to 6 January): a tree between the
# Pfalztheater and the Rathaus, string lights along the roofs after dusk.
def bulbs(points, rnd):
    cols = ["#ffe6a8", "#ffd27a", "#ff6a55", "#ffe6a8", "#9fd8ff"]
    return "".join(f'<circle cx="{x:.1f}" cy="{y:.1f}" r=".9" fill="{rnd.choice(cols)}" '
                   f'style="animation-duration:{rnd.uniform(1.6, 3.2):.1f}s;animation-delay:{-rnd.uniform(0, 3):.1f}s"/>'
                   for x, y in points)


def string(x1, x2, y, step=3.2, sag=1.2, span=13):
    pts, x = [], x1
    while x <= x2 + .01:
        k = ((x - x1) % span) / span
        pts.append((x, y + 1.6 + sag * 4 * k * (1 - k)))
        x += step
    return pts


def xmas(pal):
    rnd = random.Random(12)
    night = pal == "night"
    tree = ('<path d="M542 160 L548.5 171 L545.5 171 L551 181 L547 181 L553 193 L531 193 L537 181 L533 181 L538.5 171 L535.5 171Z" '
            f'fill="{"#12301f" if night else "#2f6b3a"}"/>'
            '<path d="M542 155.5 l1.1 2.4 l2.6 .2 l-2 1.7 l.7 2.5 l-2.4 -1.4 l-2.4 1.4 l.7 -2.5 l-2 -1.7 l2.6 -.2Z" fill="#ffd34d"/>'
            '<rect x="540.5" y="193" width="3" height="5" fill="#5a3b26"/>')
    orn = [(539, 169), (545, 170), (537, 179), (542, 177), (547, 179), (535, 189), (540, 186), (545, 188), (549, 190)]
    if night:
        lights = bulbs(orn, rnd)
        pts = (string(548, 606, 36) + string(556, 598, 28, span=14) + string(458, 534, 160, span=12) +
               string(480, 514, 150, span=12) + string(606, 698, 158, span=15) + string(782, 844, 164, span=12) +
               string(898, 952, 168, span=12) + string(300, 344, 170, span=11))
        lights += bulbs(pts, rnd)
        return overlay("", tree + f'<g class="tw">{lights}</g>', "",
                       ".tw circle{animation:tw 2.4s ease-in-out infinite}"
                       "@keyframes tw{0%,100%{opacity:1}50%{opacity:.35}}")
    balls = "".join(f'<circle cx="{x}" cy="{y}" r=".9" fill="{c}"/>'
                    for (x, y), c in zip(orn, ["#d8263a", "#e8b923", "#d8263a", "#e8b923", "#d8263a",
                                               "#e8b923", "#d8263a", "#e8b923", "#d8263a"]))
    return overlay("", tree + balls, "")


write("kl-xmas-day.svg", xmas("day"))
write("kl-xmas-night.svg", xmas("night"))


