def sun(low):
    c = 60
    core, rim, glow = (("#ffb35c", "#ffd08a", "#ff9a3c") if low else ("#ffe27a", "#fff4c2", "#ffe28a"))
    rays = "" if low else '<g class="rays" fill="#fff2b0" fill-opacity=".7">' + "".join(
        f'<rect x="{c - 1.25:.2f}" y="{c - 31}" width="2.5" height="8.5" rx="1.25" transform="rotate({a} {c} {c})"/>'
        for a in range(0, 360, 30)) + "</g>"
    return f"""
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 120" width="120" height="120">
  <defs><radialGradient id="g"><stop offset="0" stop-color="{rim}" stop-opacity=".8"/>
  <stop offset=".35" stop-color="{glow}" stop-opacity=".35"/><stop offset="1" stop-color="{glow}" stop-opacity="0"/></radialGradient></defs>
  <style>
    .glow{{transform-origin:{c}px {c}px;animation:pulse 6s ease-in-out infinite}}
    .rays{{transform-origin:{c}px {c}px;animation:spin 90s linear infinite}}
    @keyframes pulse{{0%,100%{{transform:scale(1);opacity:.85}}50%{{transform:scale(1.1);opacity:1}}}}
    @keyframes spin{{to{{transform:rotate(360deg)}}}}
    {RM}
  </style>
  <circle class="glow" cx="{c}" cy="{c}" r="58" fill="url(#g)"/>
  {rays}
  <circle cx="{c}" cy="{c}" r="{15 if low else 13}" fill="{rim}"/>
  <circle cx="{c}" cy="{c}" r="{12.5 if low else 10.8}" fill="{core}"/>
</svg>"""


write("kl-sunball.svg", sun(False))
write("kl-sunlow.svg", sun(True))


def moon_path(cx, cy, r, p):
    k = math.cos(2 * math.pi * p)
    rx = r * abs(k)
    if p < .5:   # waxing: lit on the right
        s1, s2 = 1, (0 if k > 0 else 1)
    else:        # waning: lit on the left
        s1, s2 = 0, (1 if k > 0 else 0)
    return (f"M{cx} {cy - r} A{r} {r} 0 0 {s1} {cx} {cy + r} "
            f"A{rx:.2f} {r} 0 0 {s2} {cx} {cy - r}Z")


def moon(i):
    c, r = 45, 10
    lit = moon_path(c, c, r, i / 8)
    return f"""
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 90 90" width="90" height="90">
  <defs><radialGradient id="mg"><stop offset="0" stop-color="#e8ecff" stop-opacity=".6"/><stop offset="1" stop-color="#e8ecff" stop-opacity="0"/></radialGradient>
  <clipPath id="lit"><path d="{lit}"/></clipPath></defs>
  <circle cx="{c}" cy="{c}" r="30" fill="url(#mg)" fill-opacity="{.25 + .5 * math.sin(math.pi * i / 8):.2f}"/>
  <circle cx="{c}" cy="{c}" r="{r}" fill="#c8d2e6" fill-opacity=".12"/>
  <path d="{lit}" fill="#f1f0e4"/>
  <g fill="#d6d3c2" fill-opacity=".55" clip-path="url(#lit)">
    <circle cx="{c - 3}" cy="{c - 2.3}" r="2"/><circle cx="{c + 3}" cy="{c + 3}" r="1.5"/>
    <circle cx="{c + 1.5}" cy="{c - 4.6}" r="1"/><circle cx="{c - 2.3}" cy="{c + 4.6}" r="1.2"/></g>
</svg>"""


for i in range(1, 8):
    write(f"kl-moon-{i}.svg", moon(i))


