# --------------------------------------------------------------------------
# Clouds: seamless horizontal loop (content repeated at +600)
# --------------------------------------------------------------------------
def cloud(rnd, cx, cy, w, body, shade):
    h = w * rnd.uniform(.32, .42)
    parts = [f'<ellipse cx="{cx:.1f}" cy="{cy:.1f}" rx="{w / 2:.1f}" ry="{h * .42:.1f}"/>']
    n = rnd.randint(3, 4)
    for j in range(n):
        bx = cx - w * .32 + (w * .64) * j / (n - 1) + rnd.uniform(-4, 4)
        br = h * rnd.uniform(.45, .72) * (1.2 if 0 < j < n - 1 else .85)
        parts.append(f'<circle cx="{bx:.1f}" cy="{cy - h * .18:.1f}" r="{br:.1f}"/>')
    base = f'<ellipse cx="{cx:.1f}" cy="{cy + h * .22:.1f}" rx="{w * .46:.1f}" ry="{h * .2:.1f}" fill="{shade}"/>'
    return f'<g fill="{body}">{"".join(parts)}{base}</g>'


CLOUD_PAL = {
    # (far colour, near colour, shade, far opacity, near opacity)
    "day":      ("#ffffff", "#f6f9fc", "#d5dfe9", .5, .82),
    "light":    ("#c9d1d9", "#d6dde4", "#aeb8c3", .7, .8),
    "dark":     ("#7b8794", "#8e99a5", "#636e7a", .75, .92),
    "storm":    ("#3e4557", "#4b5266", "#2c3242", .85, .95),
    "twilight": ("#8f7889", "#a68f9a", "#6f5d6e", .6, .8),
    "night":    ("#4a5878", "#5b6888", "#38445f", .45, .6),
}


def clouds(kind, pal, speed, d):
    far_c, near_c, shade, far_o, near_o = CLOUD_PAL[pal]
    rnd = random.Random(11 if kind == "partly" else 23)
    if kind == "partly":
        far = [(x, rnd.uniform(18, 60), rnd.uniform(40, 70)) for x in (60, 260, 450)]
        near = [(x, rnd.uniform(28, 70), rnd.uniform(70, 110)) for x in (140, 370, 560)]
        deck = ""
    else:
        far = [(x, rnd.uniform(10, 50), rnd.uniform(90, 140)) for x in range(20, 600, 85)]
        near = [(x, rnd.uniform(30, 80), rnd.uniform(110, 170)) for x in range(40, 600, 110)]
        deck = (f'<defs><linearGradient id="deck" x1="0" y1="0" x2="0" y2="1">'
                f'<stop offset="0" stop-color="{near_c}" stop-opacity="{near_o * .85}"/>'
                f'<stop offset="1" stop-color="{near_c}" stop-opacity="0"/></linearGradient></defs>'
                f'<rect width="600" height="70" fill="url(#deck)"/>')

    def layer(items, colour):
        one = "".join(cloud(rnd, x, y, w, colour, shade) for x, y, w in items)
        return one + f'<g transform="translate({-600 if d == "r" else 600},0)">{one}</g>'

    f_dur, n_dur = (240, 140) if speed == "calm" else (70, 38)
    return f"""
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 200" preserveAspectRatio="xMidYMid slice">
  <style>
    .f{{animation:drift {f_dur}s linear infinite}}
    .n{{animation:drift {n_dur}s linear infinite}}
    @keyframes drift{{to{{transform:translateX({600 if d == "r" else -600}px)}}}}
    {RM}
  </style>
  {deck}
  <g opacity="{far_o}"><g class="f">{layer(far, far_c)}</g></g>
  <g opacity="{near_o}"><g class="n">{layer(near, near_c)}</g></g>
</svg>"""


for kind, pals in {"partly": ["day", "twilight", "night"],
                   "overcast": ["light", "dark", "storm", "twilight", "night"]}.items():
    for pal in pals:
        for speed in ("calm", "windy"):
            for d in ("l", "r"):
                write(f"kl-clouds-{kind}-{pal}-{speed}-{d}.svg", clouds(kind, pal, speed, d))


