# --------------------------------------------------------------------------
# Fog: soft bands drifting over the lower town
# --------------------------------------------------------------------------
def fog(pal):
    col, op = {"day": ("#e6eaee", .5), "night": ("#8592a8", .35)}[pal]
    rnd = random.Random(5)

    def bands(y0, y1, n):
        one = "".join(f'<ellipse cx="{rnd.uniform(0, 600):.0f}" cy="{rnd.uniform(y0, y1):.0f}" '
                      f'rx="{rnd.uniform(140, 240):.0f}" ry="{rnd.uniform(10, 20):.0f}"/>' for _ in range(n))
        return one + f'<g transform="translate(-600,0)">{one}</g>'
    return f"""
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 200" preserveAspectRatio="xMidYMax slice">
  <defs><radialGradient id="m"><stop offset="0" stop-color="{col}" stop-opacity="{op}"/>
  <stop offset="1" stop-color="{col}" stop-opacity="0"/></radialGradient>
  <linearGradient id="v" x1="0" y1="0" x2="0" y2="1"><stop offset=".35" stop-color="{col}" stop-opacity="0"/>
  <stop offset="1" stop-color="{col}" stop-opacity="{op * .8}"/></linearGradient></defs>
  <style>
    .a{{animation:drift 80s linear infinite}}
    .b{{animation:drift 130s linear infinite reverse}}
    @keyframes drift{{to{{transform:translateX(600px)}}}}
    {RM}
  </style>
  <rect width="600" height="200" fill="url(#v)"/>
  <g class="a" fill="url(#m)">{bands(110, 165, 7)}</g>
  <g class="b" fill="url(#m)">{bands(150, 200, 7)}</g>
</svg>"""


write("kl-fog-day.svg", fog("day"))
write("kl-fog-night.svg", fog("night"))


