# --------------------------------------------------------------------------
RAIN_DX = [0, 28, 60, 100]   # sideways travel per 245 px of fall, by wind level 0..3
SNOW_DX = [0, 35, 80, 130]


def drops(rnd, n, cls, length, dur, dx):
    out = []
    for _ in range(n):
        x = rnd.uniform(-10, 210)
        out.append(f'<line class="{cls}" x1="{x:.1f}" y1="0" x2="{x + length * (dx - 8) / 245:.1f}" y2="{length}" '
                   f'style="animation-duration:{rnd.uniform(*dur):.2f}s;animation-delay:{-rnd.uniform(0, 2):.2f}s"/>')
    return "".join(out)


def flakes(rnd, n, rmin, rmax, dur, cls="fl"):
    out = []
    for _ in range(n):
        x, r = rnd.uniform(-10, 210), rnd.uniform(rmin, rmax)
        out.append(f'<g class="{cls}" style="animation-duration:{rnd.uniform(*dur):.1f}s;animation-delay:{-rnd.uniform(0, 12):.1f}s">'
                   f'<circle cx="{x:.1f}" cy="0" r="{r:.1f}" style="animation-duration:{rnd.uniform(2, 3.5):.1f}s;'
                   f'animation-delay:{-rnd.uniform(0, 3):.1f}s"/></g>')
    return "".join(out)


def precip_css(rdx, sdx):
    return f"""
    .far{{stroke:#d6e4f5;stroke-opacity:.35;stroke-width:.8;stroke-linecap:round;animation:fall 1s linear infinite}}
    .near{{stroke:#e3eefb;stroke-opacity:.6;stroke-width:1.2;stroke-linecap:round;animation:fall .7s linear infinite}}
    @keyframes fall{{from{{transform:translate(0,-30px)}}to{{transform:translate({rdx - 8}px,215px)}}}}
    .fl{{animation:snow 9s linear infinite}}
    .fl circle{{fill:#fff;fill-opacity:.9;animation:sway 3s ease-in-out infinite alternate}}
    @keyframes snow{{from{{transform:translate(0,-8px)}}to{{transform:translate({sdx - 6}px,208px)}}}}
    @keyframes sway{{from{{transform:translateX(-5px)}}to{{transform:translateX(5px)}}}}
    .hl{{animation:hail .55s linear infinite}}
    .hl circle{{fill:#f4f8ff;fill-opacity:.85}}
    @keyframes hail{{from{{transform:translate(0,-8px)}}to{{transform:translate({rdx * .6 - 4:.0f}px,208px)}}}}
    {RM}
    @media (prefers-reduced-motion: reduce){{line{{stroke-opacity:.25}}}}
"""


def tile(content, rdx, sdx):
    return f"""
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200" width="200" height="200">
  <style>{precip_css(rdx, sdx)}</style>
  {content}
</svg>"""


for lvl in range(-3, 4):
    rdx = RAIN_DX[abs(lvl)] * (1 if lvl >= 0 else -1)
    sdx = SNOW_DX[abs(lvl)] * (1 if lvl >= 0 else -1)
    sfx = ("m" if lvl < 0 else "p") + str(abs(lvl))
    r = random.Random(3)
    write(f"kl-rain-{sfx}.svg", tile(drops(r, 16, "far", 8, (.9, 1.2), rdx) + drops(r, 14, "near", 13, (.6, .8), rdx), rdx, sdx))
    r = random.Random(4)
    write(f"kl-pour-{sfx}.svg", tile(drops(r, 34, "far", 10, (.7, .95), rdx) + drops(r, 30, "near", 17, (.42, .58), rdx), rdx, sdx))
    r = random.Random(6)
    write(f"kl-hail-{sfx}.svg", tile(drops(r, 14, "far", 8, (.8, 1.1), rdx) +
                                     "".join(f'<g class="hl" style="animation-duration:{r.uniform(.45, .7):.2f}s;animation-delay:{-r.uniform(0, 1):.2f}s">'
                                             f'<circle cx="{r.uniform(-10, 210):.1f}" cy="0" r="{r.uniform(1.4, 2.4):.1f}"/></g>' for _ in range(18)), rdx, sdx))
    r = random.Random(8)
    write(f"kl-sleet-{sfx}.svg", tile(drops(r, 14, "near", 12, (.6, .85), rdx) + flakes(r, 12, 1, 2, (5, 7)), rdx, sdx))
    r = random.Random(9)
    write(f"kl-snow-{sfx}.svg", tile(flakes(r, 18, .8, 1.5, (10, 14)) + flakes(r, 14, 1.6, 2.8, (6.5, 9)), rdx, sdx))



# --------------------------------------------------------------------------
# Aircraft from Ramstein (2026-11-22, refined): a C-17 and a C-5 cross the sky
# now and then (C-17 every 2 min, C-5 every 3 min; the 19 s and 31 s crossings
# never overlap: both periods are multiples of 60 s and the windows sit apart), both left to right, side views, 1 unit = 1 m (C-17 53 m, C-5 76 m), nose to +x,
# y down, fuselage axis at 0. Parts are separate shapes, each with a tone.
# They sit behind the cloud layer; beacon, strobes and nav light by day and night.
# --------------------------------------------------------------------------
def nacelle(front, y, length, h):
    """Engine pod seen from the side: intake at `front`, tapering exhaust aft."""
    r = h / 2
    body = (f"M{front} {y} h-{length - 2} c-0.8 0 -1.6 {r * .35:.2f} -2 {r:.2f} "
            f"c0.4 {r * .65:.2f} 1.2 {r:.2f} 2 {r:.2f} h{length - 2} a{r * .5:.2f} {r:.2f} 0 0 0 0 -{h}Z")
    intake = f"M{front - .5} {y + .15} a{r * .45:.2f} {r - .15:.2f} 0 0 1 0 {h - .3:.2f} a{r * .45:.2f} {r - .15:.2f} 0 0 1 0 -{h - .3:.2f}Z"
    return body, intake


def pylon(x_wing, x_pod, y_top, y_pod, w=1.4):
    return f"M{x_wing} {y_top} h{w} L{x_pod + w} {y_pod} h-{w}Z"


