def aircraft(a, pal):
    body, win, glow = {"day": ("#5a6470", "#b9c7d5", .22), "twilight": ("#2f2b3d", "#e7b8a0", .4),
                       "night": ("#161c28", "#ffd98a", .45)}[pal]
    under = hexmix(body, "#000000", .14)
    eng = hexmix(body, "#000000", .3)
    dark = hexmix(body, "#000000", .55)
    stab = hexmix(body, "#ffffff", .06)
    out = [f'<path d="{a["fin"]}" fill="{body}"/>', f'<path d="{a["stab"]}" fill="{stab}"/>',
           f'<path d="{a["bullet"]}" fill="{stab}"/>']
    out += [f'<path d="{a["pods"]}" fill="{under}"/>', f'<path d="{a["body"]}" fill="{body}"/>',
            f'<path d="{a["belly"]}" fill="{under}"/>', f'<path d="{a["fairing"]}" fill="{body}"/>',
            f'<path d="{a["wing"]}" fill="{stab}"/>',
            f'<path d="{a["winglet"]}" fill="{stab}"/>' if a["winglet"] else "",
            f'<path d="{a["door"]}" fill="{under}"/>', f'<path d="{a["windows"]}" fill="{win}"/>']
    for pl in a["pylons"]:
        out.append(f'<path d="{pl}" fill="{eng}"/>')
    for front, y, length, h in a["engines"]:
        b, intake = nacelle(front, y, length, h)
        out += [f'<path d="{b}" fill="{eng}"/>', f'<path d="{intake}" fill="{dark}"/>']
    L = a["lights"]
    nav = "#3ee07a"  # both fly left to right: we see the right (green) wingtip

    def dot(xy, col, cls, r):
        x, y = xy
        c = f' class="{cls}"' if cls else ""
        return (f'<g{c}><circle cx="{x}" cy="{y}" r="{r * 2.6:.2f}" fill="{col}" opacity="{glow}"/>'
                f'<circle cx="{x}" cy="{y}" r="{r}" fill="{col}"/></g>')
    out += [dot(L["beacon"], "#ff3b30", "bc", .8), dot(L["belly"], "#ff3b30", "bc", .7),
            dot(L["strobe"], "#ffffff", "sb", .8), dot(L["tail"], "#ffffff", "sb", .6),
            dot(L["nav"], nav, "", .6)]
    return "".join(out)


def planes(pal):
    return f"""
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 200" preserveAspectRatio="xMidYMid slice">
  <style>
    .c17{{animation:c17 120s linear infinite;animation-delay:-100s}}
    .c5{{animation:c5 180s linear infinite;animation-delay:-136s}}
    @keyframes c17{{0%{{transform:translate(-90px,44px)}}16%{{transform:translate(690px,30px)}}16.01%,100%{{transform:translate(900px,0)}}}}
    @keyframes c5{{0%{{transform:translate(-130px,62px)}}17%{{transform:translate(700px,50px)}}17.01%,100%{{transform:translate(900px,0)}}}}
    .bc{{animation:bc 1.2s steps(1) infinite}} .sb{{animation:sb 1.5s steps(1) infinite;opacity:0}}
    @keyframes bc{{0%{{opacity:1}}50%{{opacity:.15}}}}
    @keyframes sb{{0%{{opacity:1}}8%{{opacity:0}}}}
    {RM}
    @media (prefers-reduced-motion: reduce){{.c17,.c5{{transform:translate(900px,0)}}}}
  </style>
  <g opacity=".95">
    <g class="c17"><g transform="scale(.95)">{aircraft(AIRCRAFT["c17"], pal)}</g></g>
    <g class="c5"><g transform="scale(.95)">{aircraft(AIRCRAFT["c5"], pal)}</g></g>
  </g>
</svg>"""


for pal in ("day", "twilight", "night"):
    write(f"kl-planes-{pal}.svg", planes(pal))
